DROP TABLE IF EXISTS `agent_location_pings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `agent_location_pings` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `agent_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `route_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lat` double NOT NULL,
  `lng` double NOT NULL,
  `accuracy_m` double DEFAULT NULL,
  `speed_mps` double DEFAULT NULL,
  `captured_at` datetime(3) NOT NULL,
  `received_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `branch_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ping_type` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'heartbeat',
  `is_on_duty` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `agent_location_pings_tenant_id_agent_id_captured_at_idx` (`tenant_id`,`agent_id`,`captured_at`),
  KEY `agent_location_pings_route_id_captured_at_idx` (`route_id`,`captured_at`),
  KEY `agent_location_pings_agent_id_fkey` (`agent_id`),
  KEY `agent_location_pings_branch_id_captured_at_idx` (`branch_id`,`captured_at`),
  KEY `agent_location_pings_tenant_id_received_at_idx` (`tenant_id`,`received_at`),
  CONSTRAINT `agent_location_pings_agent_id_fkey` FOREIGN KEY (`agent_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `agent_location_pings_branch_id_fkey` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `agent_location_pings_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
